entries[442649] = { ["name"] = "Infusion: Crystal", ["text"] = "2 sec cast\nReagents:\nElusive Creature Lure , Crystalline Powder (3)\nSpecialization:\nLuring - Impressive Infuser\n\nCrystalline Creature Lure\nBinds when picked up\nUse: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\nThe cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\nOnly usable outdoors in Khaz Algar.\n70\n\"An enticing bait to draw elusive creatures out of hiding. Infused with crystalline power.\"" }
entries[442650] = { ["name"] = "Infusion: Spores", ["text"] = "2 sec cast\nReagents:\nElusive Creature Lure , Viridescent Spores (3)\nSpecialization:\nLuring - Impressive Infuser (20)\n\nSporefused Creature Lure\nBinds when picked up\nUse: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\nThe cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\nOnly usable outdoors in Khaz Algar.\n70\n\"An enticing bait to draw elusive creatures out of hiding. Infused with magical spores.\"" }
entries[442651] = { ["name"] = "Infusion: Writhing", ["text"] = "2 sec cast\nReagents:\nElusive Creature Lure , Writhing Sample\nSpecialization:\nLuring - Impressive Infuser (40)\n\nWrithing Creature Lure\nBinds when picked up\nUse: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\nThe cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\nOnly usable outdoors in Khaz Algar.\n70\n\"An enticing bait to draw elusive creatures out of hiding. Infused with essence that weeps with malevolent energy.\"" }
entries[442652] = { ["name"] = "Elusive Creature Lure", ["text"] = "2 sec cast\nReagents:\nBasically Beef (10)\nSpecialization:\nLuring\n\nElusive Creature Lure\nBinds when picked up\nUse: Place the bait, luring an elusive creature after a small amount of time. Who knows what might show up?\n\nThe cooldown of Elusive Creature Bait is lowered by skinning creatures in Khaz Algar.\n\nOnly usable outdoors in Khaz Algar.\n70\nRequires Khaz Algar Skinning\n(1)\n\"An enticing bait to draw elusive creatures out of hiding.\"" }
