entries[443560] = { ["name"] = "Swift and Painful", ["text"] = "Blood\nIf no enemies are struck by Soul Rupture, you gain 10% Strength for 8 sec.\n\nWave of Souls is 100% more effective on the main target of your Reaper's Mark.\n\nFrost\nIf no enemies are struck by Soul Rupture, you gain 5% Strength for 8 sec.\n\nWave of Souls is 50% more effective on the main target of your Reaper's Mark." }
