entries[443739] = { ["name"] = "Splintering Sorcery", ["text"] = "Arcane\nWhen you consume Nether Precision, conjure 2 Arcane Splinters.\n\nArcane Splinter :\nConjure raw Arcane magic into a sharp projectile that deals (40.4% of Spell Power) Arcane damage.\n\nArcane Splinters embed themselves into their target, dealing (40.4352% of Spell Power) Arcane damage over 18 sec. This effect stacks.\n\nFrost\nWhen you consume Winter's Chill or Fingers of Frost, conjure a Frost Splinter.\n\nFrost Splinter :\nConjure raw Frost magic into a sharp projectile that deals (34.32% of Spell Power) Frost damage.\n\nFrost Splinters embed themselves into their target, dealing (34.2% of Spell Power) Frost damage over 18 sec. This effect stacks." }
entries[443740] = { ["name"] = "Embedded Frost Splinter", ["text"] = "100 yd range\nInstant\nConjure raw Frost magic into a sharp projectile that deals (34.32% of Spell Power) Frost damage.\n\nFrost Splinters embed themselves into their target, dealing (34.2% of Spell Power) Frost damage over 18 sec. This effect stacks." }
