entries[443742] = { ["name"] = "Splinterstorm", ["text"] = "Arcane\nWhenever you have 8 or more active Embedded Arcane Splinters, you automatically cast a Splinterstorm at your target.\n\nSplinterstorm :\nShatter all Embedded Arcane Splinters, dealing their remaining periodic damage instantly.\n\nConjure an Arcane Splinter for each Splinter shattered, then unleash them all in a devastating barrage, dealing (40.4% of Spell Power) Arcane damage to your target for each Splinter in the Splinterstorm.\n\nSplinterstorm has a 8% chance to grant Clearcasting.\n\nFrost\nWhenever you have 8 or more active Embedded Frost Splinters, you automatically cast a Splinterstorm at your target.\n\nSplinterstorm :\nShatter all Embedded Frost Splinters, dealing their remaining periodic damage instantly.\n\nConjure a Frost Splinter for each Splinter shattered, then unleash them all in a devastating barrage, dealing (34.32% of Spell Power) Frost damage to your target for each Splinter in the Splinterstorm.\n\nSplinterstorm has a 10% chance to grant Brain Freeze." }
entries[443743] = { ["name"] = "Blessed Weapon Grip", ["text"] = "Approximately 1 procs per minute\nDamaging a target has a low chance to call upon the power of the Blessed Weapon Grip, granting you 10 stacks that increase your highest secondary stat by 185 . These stacks fade over 30 sec." }
